insert into public.products (id, slug, name, category_id, district, commune, ethnicities, image_alt, description, nutrition, safety, storage, unit, market_min, market_max, import_price, price, stock, featured, certs)
values
  ('sp-01', 'cam-long-vang-cao-phong', 'Cam lòng vàng Cao Phong', 'trai-cay', 'Huyện Cao Phong', 'Thị trấn Cao Phong', array['Mường', 'Kinh']::text[], 'Chùm cam lòng vàng chín mọng trên cành tại đồi Cao Phong, kèm mặt cắt quả cam vỏ mỏng', 'Chùm cam chín vàng tươi trên cành tại đồi Cao Phong kèm mặt cắt ngang quả cam vỏ mỏng, tép mọng nước.', 'Giàu Vitamin C (53 mg/100g) và Kali, hỗ trợ tăng cường miễn dịch.', 'Canh tác theo tiêu chuẩn VietGAP, có nhật ký chăm sóc và thời gian cách ly thuốc trước thu hoạch.', 'Bảo quản 8–12°C, độ ẩm 85–90%; dùng trong 7–10 ngày.', 'Túi lưới 2kg', 42000, 48000, 30000, 38000, 60, true, array['VietGAP', 'Không chất bảo quản']::text[]),
  ('sp-02', 'cam-xa-doai-cao-phong', 'Cam Xã Đoài Cao Phong', 'trai-cay', 'Huyện Cao Phong', 'Thị trấn Cao Phong', array['Kinh', 'Mường']::text[], 'Quả cam Xã Đoài vỏ mỏng rám nhẹ đặc trưng, ruột vàng óng đặt trên mẹt tre', 'Quả cam vỏ mỏng rám nhẹ đặc trưng, ruột vàng óng, đặt trên mẹt tre.', 'Đường tự nhiên Brix 11–13%, giàu flavonoid chống oxy hóa; vị ngọt đậm hậu thơm.', 'Vườn cam lâu năm tại Cao Phong, thu hoạch đúng độ chín, phân loại tại vườn.', 'Nơi thoáng mát 10–15°C; tránh xếp chồng nặng làm dập vỏ.', 'Kg', 50000, 55000, 35000, 44000, 40, false, array['VietGAP']::text[]),
  ('sp-03', 'buoi-do-tan-lac', 'Bưởi đỏ Tân Lạc', 'trai-cay', 'Huyện Tân Lạc', '', array['Mường']::text[], 'Quả bưởi đỏ tròn cân đối đặt cạnh đĩa múi bưởi màu đỏ hồng ráo nước', 'Quả bưởi tròn cân đối đặt cạnh đĩa múi bưởi màu đỏ hồng ráo nước.', 'Giàu Lycopene (sắc tố đỏ tự nhiên), Vitamin A và C, hỗ trợ tiêu hóa.', 'Canh tác tại vườn đồi Tân Lạc, không dùng chất bảo quản sau thu hoạch.', 'Để nơi thoáng 15–25°C được 3–4 tuần; tránh ánh nắng trực tiếp.', 'Quả (0,9–1,2kg)', 32000, 38000, 21000, 28000, 50, true, array['Không chất bảo quản']::text[]),
  ('sp-04', 'buoi-dien-yen-thuy', 'Bưởi Diễn Yên Thủy', 'trai-cay', 'Huyện Yên Thủy', '', array['Mường', 'Kinh']::text[], 'Bưởi Diễn vỏ vàng sậm bóng mịn, múi tôm vàng nhạt ráo tay', 'Bưởi vỏ vàng sậm bóng mịn, múi tôm vàng nhạt ráo tay.', 'Giàu chất xơ hòa tan Pectin, hỗ trợ tiêu hóa và cảm giác no lâu.', 'Thu hoạch đúng độ già sinh lý, bảo quản thoáng tự nhiên không hóa chất.', 'Bảo quản thoáng mát được 1–2 tháng; treo cuống để tránh mốc.', 'Quả', 28000, 34000, 18000, 24000, 50, false, array['Không chất bảo quản']::text[]),
  ('sp-05', 'quyt-on-doi-nam-son-van-son', 'Quýt ôn đới Nam Sơn – Vân Sơn', 'trai-cay', 'Huyện Tân Lạc', 'Xã Vân Sơn', array['Mường']::text[], 'Rổ quýt vỏ mỏng màu vàng cam tươi hái từ vùng cao nguyên Vân Sơn', 'Rổ quýt vỏ mỏng màu vàng cam tươi hái từ vùng cao nguyên Vân Sơn.', 'Giàu Beta-carotene và Vitamin C, vị ngọt thanh đặc trưng vùng cao.', 'Sinh trưởng trên 800m, ít sâu bệnh, không dùng thuốc bảo vệ thực vật hóa học.', 'Bảo quản 10–15°C; ăn trong 7–10 ngày.', 'Túi 1kg', 35000, 40000, 24000, 30000, 35, false, array['Không thuốc BVTV hóa học']::text[]),
  ('sp-06', 'chanh-dao-muong-dong', 'Chanh đào Mường Động', 'trai-cay', 'Huyện Kim Bôi', 'Xã Mường Động', array['Mường']::text[], 'Quả chanh đào vỏ xanh ánh vàng, cắt đôi lộ ruột hồng đào mọng nước', 'Những quả chanh vỏ xanh ánh vàng, cắt đôi lộ ruột hồng đào mọng nước.', 'Chứa tinh dầu Limonene và Axit Citric tự nhiên, hỗ trợ kháng khuẩn vòm họng.', 'Vườn chanh Mường Động chăm sóc thủ công, không dùng chất bảo quản.', 'Ngăn mát 8–10°C được 2–3 tuần.', 'Túi 1kg', 30000, 35000, 20000, 25000, 20, false, array['Không chất bảo quản']::text[]),
  ('sp-07', 'chuoi-tieu-hong-lac-thuy', 'Chuối tiêu hồng Lạc Thủy', 'trai-cay', 'Huyện Lạc Thủy', '', array['Kinh', 'Mường']::text[], 'Nải chuối tiêu hồng chín vàng đều tự nhiên, quả cong đẹp không đốm thâm', 'Nải chuối chín vàng đều tự nhiên, quả cong đẹp không đốm thâm hóa chất.', 'Giàu Kali, Vitamin B6 và Tryptophan, cung cấp năng lượng nhanh cho học sinh.', 'Chín tự nhiên bằng cách ủ ấm, không dùng thuốc thúc chín.', 'Treo nơi thoáng 18–22°C; không để trong túi kín.', 'Nải (12–16 quả)', 22000, 26000, 14000, 18000, 30, false, array['Không hóa chất thúc chín']::text[]),
  ('sp-08', 'ngon-su-su-quyet-chien', 'Ngọn su su Quyết Chiến', 'rau-cu', 'Huyện Tân Lạc', 'Xã Vân Sơn', array['Mường']::text[], 'Bó ngọn su su xanh mướt, mập non đặt trong gùi tre đan tay', 'Bó ngọn su su xanh mướt, mập non đặt trong gùi tre đan tay.', 'Giàu Folate (Vitamin B9) và chất xơ, ít calo.', 'Tưới bằng nước suối tự nhiên, không dùng chất kích thích tăng trưởng.', 'Ngăn mát 4–8°C được 3–4 ngày; bọc giấy ẩm.', 'Bó 500g', 12000, 15000, 7000, 10000, 60, false, array['Nước suối tự nhiên']::text[]),
  ('sp-09', 'qua-su-su-non-lung-van', 'Quả su su non Lũng Vân', 'rau-cu', 'Huyện Tân Lạc', 'Xã Lũng Vân', array['Mường']::text[], 'Những quả su su xanh non vỏ bóng, ít gai, đựng trong rổ tre', 'Những quả su su xanh non vỏ bóng, ít gai, đựng trong rổ tre.', 'Hàm lượng nước 93%, giàu Magie và Vitamin K, hỗ trợ chuyển hóa năng lượng.', 'Vùng cao Lũng Vân, canh tác tự nhiên, không chất kích thích sinh trưởng.', 'Nơi khô mát 10–15°C được 1–2 tuần.', 'Túi 1kg', 15000, 18000, 9000, 12000, 40, false, array['Không chất kích thích']::text[]),
  ('sp-10', 'mang-nua-rung-u-chua-kim-boi', 'Măng nứa rừng ủ chua Kim Bôi', 'rau-cu', 'Huyện Kim Bôi', '', array['Mường']::text[], 'Hũ thủy tinh trong suốt đựng lát măng nứa trắng ngà ngâm cùng ớt đỏ và tỏi', 'Hũ nhựa nguyên sinh trong suốt thấy rõ lát măng nứa trắng ngà ngâm cùng ớt đỏ và tỏi.', 'Giàu chất xơ; lên men lactic sinh lợi khuẩn hỗ trợ tiêu hóa.', 'Lên men lactic tự nhiên ở pH 3,8–4,2, không dùng chất bảo quản.', 'Ủ 20–28°C đến khi chua; sau đó bảo quản 4–8°C, dùng trong 1 tháng.', 'Hũ 1kg', 30000, 35000, 18000, 25000, 35, true, array['Lên men tự nhiên', 'Không chất bảo quản']::text[]),
  ('sp-11', 'mang-vau-dang-tuoi-da-bac', 'Măng vầu đắng tươi Đà Bắc', 'rau-cu', 'Huyện Đà Bắc', '', array['Tày', 'Dao', 'Mường']::text[], 'Búp măng vầu tươi mới đào còn nguyên bẹ vỏ nâu tím phủ lớp lông mịn', 'Búp măng vầu tươi mới đào còn nguyên bẹ vỏ nâu tím phủ lớp lông mịn.', 'Giàu chất xơ không hòa tan và khoáng chất, ít năng lượng.', 'Khai thác bền vững từ rừng tự nhiên đầu mùa, không ngâm hóa chất.', 'Luộc sơ rồi ngăn mát 4°C được 3–5 ngày; cấp đông nếu để lâu.', 'Kg', 25000, 30000, 15000, 20000, 30, false, array['Khai thác bền vững']::text[]),
  ('sp-12', 'rau-sang-huong-son-lac-thuy', 'Rau sắng Hương Sơn – Lạc Thủy', 'rau-cu', 'Huyện Lạc Thủy', 'Xã Hương Sơn', array['Mường', 'Kinh']::text[], 'Bó ngọn rau sắng lá non xanh đậm kèm chùm hoa sắng nhỏ màu trắng ngà', 'Bó ngọn rau sắng lá non xanh đậm kèm chùm hoa sắng nhỏ màu trắng ngà.', 'Đạm thực vật ~6,5g/100g và Axit Glutamic tự nhiên tạo vị ngọt thanh.', 'Thu hái từ rừng tự nhiên, không phun thuốc; rửa sạch trước khi nấu.', 'Ngăn mát 4–8°C, dùng trong 2–3 ngày.', 'Bó 300g', 30000, 36000, 20000, 25000, 25, false, array['Rừng tự nhiên']::text[]),
  ('sp-13', 'khoai-so-nuong-mai-chau', 'Khoai sọ nương Mai Châu', 'rau-cu', 'Huyện Mai Châu', '', array['Thái']::text[], 'Rổ củ khoai sọ tròn đều vỏ nâu sần đặt cạnh bát khoai luộc chín bở tơi', 'Rổ củ khoai sọ tròn đều vỏ nâu sần đặt cạnh bát khoai luộc chín bở tơi.', 'Giàu tinh bột kháng tiêu hóa (Resistant Starch) và Kali.', 'Canh tác nương rẫy không phân bón hóa học.', 'Nơi khô mát 15–20°C được 2–3 tuần; không rửa trước khi cất.', 'Túi 1kg', 28000, 32000, 18000, 23000, 30, false, array['Không phân bón hóa học']::text[]),
  ('sp-14', 'gung-trau-doi-da-luong-son', 'Gừng trâu đồi đá Lương Sơn', 'rau-cu', 'Huyện Lương Sơn', '', array['Mường', 'Kinh']::text[], 'Củ gừng già chắc nịch, ruột vàng đậm, bám đất đồi khô ráo', 'Củ gừng già chắc nịch, ruột vàng đậm, bám đất đồi khô ráo.', 'Hoạt chất Gingerol và tinh dầu cay ấm, hỗ trợ tiêu hóa và giữ ấm cơ thể.', 'Trồng trên đất đồi đá, thu hoạch đúng độ già, không chất bảo quản.', 'Nơi khô thoáng được 3–4 tuần; ngăn mát bọc giấy.', 'Túi 1kg', 32000, 38000, 20000, 26000, 20, false, array['Không chất bảo quản']::text[]),
  ('sp-15', 'gao-nep-nuong-mai-chau', 'Gạo nếp nương Mai Châu', 'gao-kho', 'Huyện Mai Châu', '', array['Thái']::text[], 'Túi gạo nếp hạt to tròn trắng đục đặt cạnh chõ xôi ngũ sắc dẻo bóng', 'Túi gạo nếp hạt to tròn trắng đục đặt cạnh chõ xôi ngũ sắc dẻo bóng.', 'Giàu tinh bột Amylopectin (~80%) và Vitamin B1; đồ xôi dẻo mềm lâu.', 'Lúa nương Mai Châu phơi khô tự nhiên, xay xát tại địa phương, không đánh bóng.', 'Nơi khô mát, đậy kín; ngăn mát để tránh mọt.', 'Túi hút chân không 2kg', 76000, 84000, 58000, 70000, 30, true, array['Hút chân không']::text[]),
  ('sp-16', 'gao-nep-cam-da-bac', 'Gạo nếp cẩm vùng cao Đà Bắc', 'gao-kho', 'Huyện Đà Bắc', '', array['Tày', 'Dao']::text[], 'Hạt gạo nếp cẩm màu tím than tự nhiên bóng đẹp trong bát gỗ', 'Hạt gạo nếp cẩm màu tím than tự nhiên bóng đẹp trong bát gỗ.', 'Lớp cám giàu Anthocyanin chống oxy hóa, bổ sung Sắt và Vitamin E.', 'Nếp cẩm nương vùng cao, màu tím tự nhiên từ hạt, không phẩm màu.', 'Đậy kín nơi khô mát; dùng trong 3 tháng.', 'Túi hút chân không 1kg', 45000, 50000, 32000, 39000, 25, false, array['Hút chân không']::text[]),
  ('sp-17', 'gao-te-rau-lac-son', 'Gạo tẻ râu đặc sản Lạc Sơn', 'gao-kho', 'Huyện Lạc Sơn', '', array['Mường']::text[], 'Hạt gạo tẻ thon dài trắng trong đặt cạnh bát cơm trắng dẻo thơm', 'Hạt gạo tẻ thon dài trắng trong đặt cạnh bát cơm trắng dẻo thơm.', 'Giàu Protein và khoáng chất vi lượng, cơm thơm dẻo vừa.', 'Lúa ruộng bậc thang tưới nước suối, canh tác 6 tháng, phơi khô tự nhiên.', 'Nơi khô mát, tránh ẩm; dùng trong 3–6 tháng.', 'Túi 5kg', 125000, 135000, 95000, 112000, 20, false, array['Ruộng bậc thang']::text[]),
  ('sp-18', 'mien-dong-nguyen-chat-da-bac', 'Miến dong nguyên chất Đà Bắc', 'gao-kho', 'Huyện Đà Bắc', '', array['Tày', 'Dao', 'Mường']::text[], 'Bó miến sợi màu xám hổ phách tự nhiên phơi trên phên nứa dưới nắng vùng cao', 'Bó miến sợi màu xám hổ phách tự nhiên phơi trên phên nứa dưới nắng vùng cao.', 'Làm 100% từ tinh bột củ dong riềng đỏ, chỉ số đường huyết thấp.', 'Không dùng chất tẩy trắng lưu huỳnh; sợi xám tự nhiên, phơi nắng.', 'Bảo quản khô ráo, thoáng mát; dùng trong 6 tháng.', 'Gói 500g', 38000, 44000, 26000, 34000, 40, false, array['Không tẩy trắng', 'Sấy nắng tự nhiên']::text[]),
  ('sp-19', 'mang-kho-luoi-lon-mai-chau', 'Măng khô lưỡi lợn phơi nắng Mai Châu', 'gao-kho', 'Huyện Mai Châu', '', array['Thái']::text[], 'Những miếng măng khô dày dặn màu vàng hổ phách tự nhiên, không mốc', 'Những miếng măng khô dày dặn, màu vàng hổ phách tự nhiên, không mốc.', 'Giàu chất xơ; quy trình sấy giảm hoạt độ nước a_w < 0,55 giúp bảo quản an toàn.', 'Luộc kỹ bằng nước suối, phơi nắng tự nhiên, không xông diêm sinh.', 'Nơi khô ráo dưới 30°C; túi hút chân không dùng trong 6 tháng.', 'Túi hút chân không 500g', 130000, 150000, 95000, 115000, 15, true, array['Sấy nắng tự nhiên', 'Không xông diêm sinh']::text[]),
  ('sp-20', 'moc-nhi-rung-yen-thuy', 'Mộc nhĩ rừng tự nhiên Yên Thủy', 'gao-kho', 'Huyện Yên Thủy', '', array['Mường', 'Kinh']::text[], 'Tai mộc nhĩ khô cánh dày, mặt trên nâu sẫm, mặt dưới có lớp lông tơ mịn', 'Tai mộc nhĩ khô cánh dày, mặt trên nâu sẫm, mặt dưới có lớp lông tơ mịn.', 'Giàu chất xơ hòa tan, Sắt và Polysaccharide hỗ trợ tuần hoàn.', 'Thu hái tự nhiên, phơi khô, không chất bảo quản.', 'Bảo quản kín nơi khô mát; dùng trong 6 tháng.', 'Túi 200g', 36000, 42000, 24000, 30000, 25, false, array['Rừng tự nhiên']::text[]),
  ('sp-21', 'nam-huong-rung-kho-tan-lac', 'Nấm hương rừng khô Tân Lạc', 'gao-kho', 'Huyện Tân Lạc', '', array['Mường']::text[], 'Túi nấm hương rừng mũ tròn cúp tự nhiên, tỏa hương thơm đặc trưng', 'Túi nấm hương rừng mũ tròn cúp tự nhiên, tỏa hương thơm đặc trưng.', 'Chứa Ergosterol (tiền Vitamin D2) và 8 axit amin thiết yếu.', 'Nấm rừng thu hái đúng loại, sấy khô, đóng gói kín.', 'Nơi khô mát, tránh ẩm; dùng trong 6 tháng.', 'Túi 200g', 75000, 85000, 52000, 65000, 15, false, array['Rừng tự nhiên', 'Sấy khô']::text[]),
  ('sp-22', 'thit-lon-muoi-chua-lac-son', 'Thịt lợn muối chua xứ Mường', 'tuoi-song', 'Huyện Lạc Sơn', '', array['Mường']::text[], 'Đĩa thịt muối chua thái lát mỏng phủ thính gạo rang vàng, ăn kèm lá sung', 'Đĩa thịt muối chua thái lát mỏng phủ thính gạo rang vàng ruộm ăn kèm lá sung, lá ổi.', 'Lợn bản nuôi thảo mộc, lên men nhờ Lactobacillus, giàu Protein dễ hấp thu.', 'Lên men tự nhiên, pH 4,2–4,6; đóng hộp sạch, không chất bảo quản.', 'Bảo quản 2–4°C; dùng trong 7–10 ngày sau khi lên men.', 'Hộp 300g', 55000, 62000, 40000, 50000, 40, true, array['Lên men tự nhiên']::text[]),
  ('sp-23', 'trung-ga-ta-lac-thuy', 'Trứng gà ta thả đồi Lạc Thủy', 'tuoi-song', 'Huyện Lạc Thủy', '', array['Kinh', 'Mường']::text[], 'Vỉ 10 quả trứng gà ta vỏ hồng nhạt, phía sau là đàn gà thả tự do trên đồi', 'Vỉ 10 quả trứng gà ta vỏ hồng nhạt kèm ảnh đàn gà thả tự do trên đồi cây.', 'Lòng đỏ giàu Choline, Omega-3 và Vitamin D nhờ ăn ngô, thóc, côn trùng.', 'Gà chăn thả tự do, không dùng kháng sinh tăng trọng; trứng thu gom trong ngày.', 'Bảo quản 4–8°C, dùng trong 3–4 tuần; không rửa trước khi cất.', 'Vỉ giấy 10 quả', 45000, 50000, 32000, 40000, 50, false, array['Chăn thả tự do']::text[]),
  ('sp-24', 'trung-vit-co-xanh-kim-boi', 'Trứng vịt cổ xanh suối Mường', 'tuoi-song', 'Huyện Kim Bôi', '', array['Mường']::text[], 'Vỉ trứng vịt vỏ xanh nhạt kích thước đồng đều đặt trong giỏ tre', 'Vỉ trứng vịt vỏ xanh nhạt kích thước đồng đều đặt trong giỏ tre.', 'Hàm lượng Protein và Sắt cao, lòng đỏ dẻo thơm.', 'Vịt bản địa chăn thả khe suối tự nhiên, thức ăn từ lúa và ốc.', '4–8°C được 3–4 tuần.', 'Vỉ giấy 10 quả', 48000, 54000, 34000, 42000, 30, false, array['Chăn thả tự nhiên']::text[]),
  ('sp-25', 'ca-tram-den-song-da-phi-le', 'Cá trắm đen lòng hồ sông Đà phi lê', 'tuoi-song', 'Huyện Đà Bắc', '', array['Mường', 'Dao']::text[], 'Khay cá trắm đen phi lê thịt săn chắc đóng gói hút chân không', 'Khay cá trắm đen cắt khúc/phi lê thịt săn chắc đóng gói hút chân không.', 'Giàu axit béo Omega-3 (EPA/DHA) tốt cho trí não.', 'Nuôi lồng trên vùng nước sạch lòng hồ sông Đà, sơ chế và hút chân không trong ngày.', '0–4°C dùng trong 2 ngày; cấp đông −18°C được 1 tháng.', 'Khay hút chân không 500g', 95000, 110000, 72000, 85000, 20, false, array['Hút chân không', 'Lòng hồ sạch']::text[]),
  ('sp-26', 'tep-dau-kho-song-da', 'Tép dầu khô lòng hồ sông Đà', 'tuoi-song', 'Huyện Đà Bắc', '', array['Tày', 'Mường']::text[], 'Đĩa tép dầu đánh bắt tự nhiên phơi khô giòn ánh bạc tự nhiên', 'Đĩa tép dầu đánh bắt tự nhiên phơi khô giòn ánh bạc tự nhiên.', 'Nguồn Canxi hữu cơ và Photpho dồi dào cho sự phát triển chiều cao.', 'Đánh bắt tự nhiên, phơi khô, không phẩm màu.', 'Bảo quản kín nơi khô mát; dùng trong 3 tháng.', 'Gói 250g', 65000, 75000, 46000, 56000, 20, false, array['Phơi khô tự nhiên']::text[]),
  ('sp-27', 'hat-doi-rung-lac-son', 'Hạt dổi rừng Lạc Sơn', 'tuoi-song', 'Huyện Lạc Sơn', '', array['Mường']::text[], 'Gói hạt dổi rừng khô màu nâu đen, bề mặt nhăn tự nhiên giàu tinh dầu', 'Gói hạt dổi rừng khô màu nâu đen, bề mặt nhăn tự nhiên giàu tinh dầu.', 'Chứa tinh dầu tự nhiên kích thích tiêu hóa, khử mùi tanh thực phẩm.', 'Thu hái từ rừng Lạc Sơn, phơi khô nguyên hạt, không tẩm ướp.', 'Bảo quản kín, tránh ẩm; dùng trong 1 năm.', 'Gói 50g', 110000, 130000, 80000, 96000, 15, false, array['Rừng tự nhiên']::text[]),
  ('sp-28', 'muoi-hat-doi-mac-khen', 'Muối hạt dổi mắc khén xứ Mường', 'tuoi-song', 'Huyện Mai Châu', '', array['Thái', 'Mường']::text[], 'Hũ thủy tinh đựng muối rang giã tay trộn hạt dổi nướng, mắc khén và ớt rừng', 'Hũ thủy tinh đựng muối rang giã tay trộn hạt dổi nướng, mắc khén và ớt rừng.', 'Gia vị chấm truyền thống, không bột ngọt, không hương liệu tổng hợp.', 'Phối trộn theo tỷ lệ chuẩn truyền thống, rang giã thủ công.', 'Đậy kín nơi khô mát; dùng trong 6 tháng.', 'Hũ 150g', 32000, 38000, 20000, 26000, 30, false, array['Không bột ngọt']::text[]),
  ('sp-29', 'mat-ong-rung-da-bac', 'Mật ong rừng nguyên chất lòng hồ Đà Bắc', 'tra-mat-ong', 'Huyện Đà Bắc', '', array['Dao', 'Tày']::text[], 'Chai thủy tinh đựng mật ong vàng sánh óng ánh đặt cạnh sáp ong rừng', 'Chai thủy tinh đựng mật ong vàng sánh óng ánh đặt cạnh sáp ong rừng.', 'Đường đơn Fructose/Glucose dễ hấp thu và enzyme kháng khuẩn tự nhiên.', 'Khai thác thủ công từ hoa rừng tự nhiên, không pha đường, không đun nóng.', '20–30°C, tránh nắng; kết tinh tự nhiên là bình thường.', 'Chai thủy tinh 500ml', 210000, 240000, 155000, 190000, 12, true, array['Nguyên chất', 'Khai thác thủ công']::text[]),
  ('sp-30', 'che-xanh-son-thuy-da-bac', 'Chè xanh vùng cao Sơn Thủy – Đà Bắc', 'tra-mat-ong', 'Huyện Đà Bắc', 'Xã Sơn Thủy', array['Dao', 'Tày', 'Mường']::text[], 'Búp chè sao khô xoăn nhỏ phủ tuyết trắng bên chén nước chè xanh vàng', 'Búp chè sao khô xoăn nhỏ phủ tuyết trắng bên chén nước chè xanh vàng.', 'Giàu Polyphenol (EGCG) và L-Theanine giúp tỉnh táo, tập trung.', 'Vùng chè sạch Sơn Thủy, sao sấy thủ công, không phẩm màu.', 'Kín, tránh ẩm và ánh sáng; ngăn mát sau khi mở túi.', 'Túi bạc hút chân không 500g', 135000, 155000, 95000, 120000, 15, false, array['Hữu cơ tự nhiên']::text[]),
  ('sp-31', 'che-shan-tuyet-pa-co', 'Chè Shan tuyết cổ thụ Pà Cò – Mai Châu', 'tra-mat-ong', 'Huyện Mai Châu', 'Xã Pà Cò', array['Mông', 'Thái']::text[], 'Búp chè 1 tôm 2 lá phủ lớp lông tơ trắng mịn như tuyết', 'Búp chè 1 tôm 2 lá phủ lớp lông tơ trắng mịn như tuyết.', 'Thu hái từ chè cổ thụ trên núi cao, giàu polyphenol và axit amin.', 'Canh tác hữu cơ tự nhiên, không thuốc bảo vệ thực vật.', 'Bảo quản kín, tránh ẩm; dùng trong 12 tháng.', 'Túi hút chân không 250g', 115000, 130000, 82000, 100000, 12, true, array['Hữu cơ tự nhiên', 'Cổ thụ']::text[]),
  ('sp-32', 'xa-den-kho-hoa-binh', 'Xạ đen khô Hòa Bình', 'tra-mat-ong', 'Huyện Kim Bôi', '', array['Mường']::text[], 'Gói thân và lá cây xạ đen sấy khô giữ nguyên màu xanh nâu tự nhiên', 'Gói thân và lá cây xạ đen sấy khô giữ nguyên màu xanh nâu tự nhiên.', 'Chứa Flavonoid và Quinon, hỗ trợ thanh nhiệt, giải độc gan.', 'Thu hái – sấy khô tự nhiên, không tẩm ướp.', 'Nơi khô mát, đậy kín; dùng trong 12 tháng.', 'Gói 500g', 65000, 75000, 42000, 54000, 20, false, array['Sấy khô']::text[]),
